    {
        static readonly object _lock = new object();
        static readonly List<(object func, object?[] args, IDictionary<string, object?>? kwargs)> _handlers = new List<(object, object?[], IDictionary<string, object?>?)>();
        static bool _hooked;

        /// <summary>register(func, *args, **kwargs): func(*args, **kwargs) runs at exit; returns func (so it works as a decorator).</summary>
        public static dynamic register(object? func, params object?[] args) => Register(func, args ?? new object?[] { null }, null);
        public static dynamic register(object? func, IDictionary<string, object?> __kwargs) => Register(func, Array.Empty<object?>(), __kwargs);

        static dynamic Register(object? func, object?[] args, IDictionary<string, object?>? kwargs)
        {
            if (func == null) throw new InvalidCastException("the first argument must be callable");
            lock (_lock)
            {
                _handlers.Add((func, args, kwargs));
                if (!_hooked)
                {
                    _hooked = true;
                    AppDomain.CurrentDomain.ProcessExit += (_, _) => _run_exitfuncs();
                }
            }
            return func;
        }

        /// <summary>unregister(func): func no longer runs at exit (however often it was registered).</summary>
        public static void unregister(object? func)
        {
            lock (_lock) _handlers.RemoveAll(h => ReferenceEquals(h.func, func) || Builtins.eq(h.func, func));
        }

        /// <summary>Runs the registered functions, last first, and forgets them.</summary>
        public static void _run_exitfuncs()
        {
            while (true)
            {
                (object func, object?[] args, IDictionary<string, object?>? kwargs) h;
                lock (_lock)
                {
                    if (_handlers.Count == 0) return;
                    h = _handlers[^1];
                    _handlers.RemoveAt(_handlers.Count - 1);
                }
                try { Builtins.__invoke_kw(h.func, h.args, h.kwargs); }
                catch (SystemExit) { }
                catch (Exception e)
                {
                    try
                    {
                        Console.Out.Flush();
                        Console.Error.Write($"Exception ignored in atexit callback {Builtins.repr(h.func)}:\n" + string.Concat(traceback.format_exception(e)));
                        Console.Error.Flush();
                    }
                    catch (Exception) { }
                }
            }
        }

        public static void _clear() { lock (_lock) _handlers.Clear(); }
        public static long _ncallbacks() { lock (_lock) return _handlers.Count; }
    }

