    /// <summary>getopt: C-style command line parsing (a port of CPython 3.15's getopt.py).</summary>
    internal static class getopt_
    {
        /// <summary>getopt.error, the old name of GetoptError (its base here, so that except error catches GetoptError).</summary>
        internal class error : Exception, IPyRepr
        {
            public string msg { get; set; } = "";
            public string opt { get; set; } = "";
            public PyTuple<object?> args { get; set; }
            public error() : this("", "") { }
            public error(string msg) : this(msg, "") { }
            public error(string msg, string opt) : base(msg) { this.msg = msg; this.opt = opt; args = new PyTuple<object?>(new object?[] { msg, opt }); }
            public error(string message, Exception innerException) : base(message, innerException) { msg = message; args = new PyTuple<object?>(new object?[] { message, "" }); }
            public string __repr__() => PyExc.Repr(this, args);
        }

        /// <summary>GetoptError(msg, opt=''): an unrecognized option or a missing argument; str() is the message.</summary>
        internal class GetoptError : error
        {
            public GetoptError() : base() { }
            public GetoptError(string msg) : base(msg) { }
            public GetoptError(string msg, string opt) : base(msg, opt) { }
            public GetoptError(string message, Exception innerException) : base(message, innerException) { }
        }

        static List<string> LongOpts(object? longopts) => longopts switch
        {
            null => new List<string>(),
            string s => new List<string> { s },
            IEnumerable e => e.Cast<object?>().Select(x => (string)x!).ToList(),
            _ => throw new InvalidCastException("longopts must be a string or a list of strings"),
        };

        /// <summary>
        /// getopt(args, shortopts, longopts=[]): (options, remaining arguments). Options are (option, value) pairs ("-a",
        /// "1"), ("--alpha", ""); parsing stops at the first non-option argument or at "--".
        /// </summary>
        public static (List<(string, string)>, List<string>) getopt(IEnumerable<string> args, string shortopts, object? longopts = null)
        {
            var opts = new List<(string, string)>();
            var longs = LongOpts(longopts);
            var a = args.ToList();
            while (a.Count > 0 && a[0].StartsWith("-") && a[0] != "-")
            {
                if (a[0] == "--") { a = a.Skip(1).ToList(); break; }
                if (a[0].StartsWith("--")) a = do_longs(opts, a[0].Substring(2), longs, a.Skip(1).ToList());
                else a = do_shorts(opts, a[0].Substring(1), shortopts, a.Skip(1).ToList());
            }
            return (opts, a);
        }

        /// <summary>
        /// gnu_getopt(args, shortopts, longopts=[]): like getopt, but options and other arguments may be mixed. A leading
        /// '+' in shortopts (or POSIXLY_CORRECT) stops at the first non-option; a leading '-' reports the non-options in
        /// place, as (None, argument) pairs (CPython groups each run of them in one (None, [arguments]) pair).
        /// </summary>
        public static (List<(string, string)>, List<string>) gnu_getopt(IEnumerable<string> args, string shortopts, object? longopts = null)
        {
            var opts = new List<(string, string)>();
            var prog_args = new List<string>();
            var longs = LongOpts(longopts);
            bool return_in_order = false, all_options_first;
            if (shortopts.StartsWith("-")) { shortopts = shortopts.Substring(1); all_options_first = false; return_in_order = true; }
            else if (shortopts.StartsWith("+")) { shortopts = shortopts.Substring(1); all_options_first = true; }
            else all_options_first = !string.IsNullOrEmpty(Environment.GetEnvironmentVariable("POSIXLY_CORRECT"));
            var a = args.ToList();
            while (a.Count > 0)
            {
                if (a[0] == "--") { prog_args.AddRange(a.Skip(1)); break; }
                if (a[0].StartsWith("--"))
                {
                    if (return_in_order && prog_args.Count > 0) { foreach (var p in prog_args) opts.Add((null!, p)); prog_args.Clear(); }
                    a = do_longs(opts, a[0].Substring(2), longs, a.Skip(1).ToList());
                }
                else if (a[0].StartsWith("-") && a[0] != "-")
                {
                    if (return_in_order && prog_args.Count > 0) { foreach (var p in prog_args) opts.Add((null!, p)); prog_args.Clear(); }
                    a = do_shorts(opts, a[0].Substring(1), shortopts, a.Skip(1).ToList());
                }
                else if (all_options_first) { prog_args.AddRange(a); break; }
                else { prog_args.Add(a[0]); a = a.Skip(1).ToList(); }
            }
            return (opts, prog_args);
        }

        static List<string> do_longs(List<(string, string)> opts, string opt, List<string> longopts, List<string> args)
        {
            string? optarg = null;
            int i = opt.IndexOf('=');
            if (i >= 0) { optarg = opt.Substring(i + 1); opt = opt.Substring(0, i); }
            var (has_arg, name) = long_has_args(opt, longopts);
            if (has_arg != "")
            {
                if (optarg == null && has_arg != "?")
                {
                    if (args.Count == 0) throw new GetoptError($"option --{name} requires argument", name);
                    optarg = args[0]; args = args.Skip(1).ToList();
                }
            }
            else if (optarg != null) throw new GetoptError($"option --{name} must not have an argument", name);
            opts.Add(("--" + name, optarg ?? ""));
            return args;
        }

        /// <summary>Whether a long option takes an argument ("" no, "1" yes, "?" optional) and its full name (a unique prefix is enough).</summary>
        static (string, string) long_has_args(string opt, List<string> longopts)
        {
            var possibilities = longopts.Where(o => o.StartsWith(opt, StringComparison.Ordinal)).ToList();
            if (possibilities.Count == 0) throw new GetoptError($"option --{opt} not recognized", opt);
            if (possibilities.Contains(opt)) return ("", opt);
            if (possibilities.Contains(opt + "=")) return ("1", opt);
            if (possibilities.Contains(opt + "=?")) return ("?", opt);
            if (possibilities.Count > 1)
                throw new GetoptError($"option --{opt} not a unique prefix; possible options: {string.Join(", ", possibilities)}", opt);
            string unique = possibilities[0];
            if (unique.EndsWith("=?")) return ("?", unique.Substring(0, unique.Length - 2));
            if (unique.EndsWith("=")) return ("1", unique.Substring(0, unique.Length - 1));
            return ("", unique);
        }

        static List<string> do_shorts(List<(string, string)> opts, string optstring, string shortopts, List<string> args)
        {
            while (optstring != "")
            {
                string opt = optstring.Substring(0, 1);
                optstring = optstring.Substring(1);
                string has_arg = short_has_arg(opt, shortopts);
                string optarg;
                if (has_arg != "")
                {
                    if (optstring == "" && has_arg != "?")
                    {
                        if (args.Count == 0) throw new GetoptError($"option -{opt} requires argument", opt);
                        optstring = args[0]; args = args.Skip(1).ToList();
                    }
                    optarg = optstring; optstring = "";
                }
                else optarg = "";
                opts.Add(("-" + opt, optarg));
            }
            return args;
        }

        static string short_has_arg(string opt, string shortopts)
        {
            for (int i = 0; i < shortopts.Length; i++)
            {
                if (opt[0] == shortopts[i] && shortopts[i] != ':')
                {
                    if (!(i + 1 < shortopts.Length && shortopts[i + 1] == ':')) return "";
                    if (i + 2 < shortopts.Length && shortopts[i + 2] == ':') return "?";
                    return "1";
                }
            }
            throw new GetoptError($"option -{opt} not recognized", opt);
        }
    }

