                    case string s: return repr_str(s, level);
                    case bool: return repr_instance(x, level);
                    case long or int or BigInteger: return repr_int(x, level);
                    case IDictionary d when x is not IPyRepr || x.GetType().Name.StartsWith("frozendict"): return x.GetType().Name.StartsWith("frozendict") ? repr_instance(x, level) : repr_dict(d, level);
                    case ITuple or IPyTuple: return repr_tuple(x, level);
                    case Array arr when arr.Rank == 1 && x is not byte[]: return repr_tuple(x, level);
                }
                var t = x?.GetType();
                if (t != null && t.IsGenericType)
                {
                    var g = t.GetGenericTypeDefinition();
                    if (g == typeof(List<>)) return repr_list((IList)x!, level);
                    if (g == typeof(HashSet<>)) return repr_set((IEnumerable)x!, level);
                    if (g == typeof(frozenset<>)) return repr_frozenset((IEnumerable)x!, level);
                    if (g == typeof(deque<>)) return repr_deque((IEnumerable)x!, level);
                    if (g == typeof(PyArray<>)) return repr_array(x!, level);
                }
                return repr_instance(x, level);
            }

            string Join(List<string> pieces, long level)
            {
                if (indent == null) return string.Join(", ", pieces);
                if (pieces.Count == 0) return "";
                string ind = indent switch
                {
                    long n when n < 0 => throw new ArgumentException($"Repr.indent cannot be negative int (was {n})"),
                    long n => new string(' ', (int)n),
                    string s => s,
                    _ => throw new InvalidCastException($"Repr.indent must be a str, int or None, not {Builtins.PyTypeName(indent.GetType())}"),
                };
                string sep = ",\n" + string.Concat(Enumerable.Repeat(ind, (int)Math.Max(0, maxlevel - level + 1)));
                string joined = string.Join(sep, new[] { "" }.Concat(pieces).Concat(new[] { "" }));
                joined = joined.Substring(1);
                return ind.Length > 0 ? joined.Substring(0, joined.Length - ind.Length) : joined;
            }

            string RepeatIterable(IEnumerable x, long level, string left, string right, long maxiter, string trail = "")
            {
                var items = x.Cast<object?>().ToList();
                int n = items.Count;
                string s;
                if (level <= 0 && n > 0) s = fillvalue;
                else
                {
                    var pieces = items.Take((int)Math.Max(0, maxiter)).Select(e => repr1(e, level - 1)).ToList();
                    if (n > maxiter) pieces.Add(fillvalue);
                    s = Join(pieces, level);
                    if (n == 1 && trail.Length > 0 && indent == null) right = trail + right;
                }
                return left + s + right;
            }

            static IEnumerable TupleItems(object x) => x switch
            {
                ITuple t => Enumerable.Range(0, t.Length).Select(i => t[i]),
                IPyTuple pt => Enumerable.Range(0, pt.Count).Select(i => pt[i]),
                IEnumerable e => e,
                _ => Array.Empty<object?>(),
            };

            static List<object?> PossiblySorted(IEnumerable x)
            {
                var items = x.Cast<object?>().ToList();
                try { return Builtins.sorted(items); }
                catch (Exception) { return items; }
            }

            public virtual string repr_tuple(object x, long level) => RepeatIterable(TupleItems(x), level, "(", ")", maxtuple, ",");
            public virtual string repr_list(IList x, long level) => RepeatIterable(x, level, "[", "]", maxlist);
            public virtual string repr_array(object x, long level)
            {
                string typecode = Builtins.str(((dynamic)x).typecode);
                var items = (IEnumerable)x;
                if (!items.Cast<object?>().Any()) return $"array('{typecode}')";
                return RepeatIterable(items, level, $"array('{typecode}', [", "])", maxarray);
            }
            public virtual string repr_set(IEnumerable x, long level) =>
                !x.Cast<object?>().Any() ? "set()" : RepeatIterable(PossiblySorted(x), level, "{", "}", maxset);
            public virtual string repr_frozenset(IEnumerable x, long level) =>
                !x.Cast<object?>().Any() ? "frozenset()" : RepeatIterable(PossiblySorted(x), level, "frozenset({", "})", maxfrozenset);
            public virtual string repr_deque(IEnumerable x, long level) => RepeatIterable(x, level, "deque([", "])", maxdeque);
            public virtual string repr_dict(IDictionary x, long level)
            {
                int n = x.Count;
                if (n == 0) return "{}";
                if (level <= 0) return "{" + fillvalue + "}";
                var pieces = new List<string>();
                foreach (var key in PossiblySorted(x.Keys).Take((int)Math.Max(0, maxdict)))
                    pieces.Add(repr1(key, level - 1) + ": " + repr1(x[key!], level - 1));
                if (n > maxdict) pieces.Add(fillvalue);
                return "{" + Join(pieces, level) + "}";
            }
            public virtual string repr_str(string x, long level)
            {
                string s = Builtins.repr(x.Length > maxstring ? x.Substring(0, (int)Math.Max(0, maxstring)) : x);
                if (s.Length > maxstring)
                {
                    int i = (int)Math.Max(0, (maxstring - 3) / 2), j = (int)Math.Max(0, maxstring - 3 - i);
                    s = Builtins.repr(x.Substring(0, Math.Min(i, x.Length)) + x.Substring(Math.Max(0, x.Length - j)));
                    s = s.Substring(0, Math.Min(i, s.Length)) + fillvalue + s.Substring(Math.Max(0, s.Length - j));
                }
                return s;
            }
            public virtual string repr_int(object x, long level)
            {
                string s = Builtins.repr(x);
                if (s.Length > maxlong)
                {
                    int i = (int)Math.Max(0, (maxlong - 3) / 2), j = (int)Math.Max(0, maxlong - 3 - i);
                    s = s.Substring(0, i) + fillvalue + s.Substring(s.Length - j);
                }
                return s;
            }
            public virtual string repr_instance(object? x, long level)
            {
                string s;
                try { s = Builtins.repr(x); }
                catch (Exception) { return $"<{(x == null ? "NoneType" : Builtins.PyTypeName(x.GetType()))} instance at 0x{RuntimeHelpers.GetHashCode(x):x}>"; }
                if (s.Length > maxother)
                {
                    int i = (int)Math.Max(0, (maxother - 3) / 2), j = (int)Math.Max(0, maxother - 3 - i);
                    s = s.Substring(0, i) + fillvalue + s.Substring(s.Length - j);
                }
                return s;
            }
        }

        /// <summary>The Repr instance behind reprlib.repr.</summary>
        public static readonly Repr aRepr = new Repr();
        /// <summary>repr(obj): obj's repr with aRepr's limits ('[0, 1, 2, 3, 4, 5, ...]').</summary>
        public static string repr(object? x) => aRepr.repr(x);

        /// <summary>
        /// @recursive_repr(fillvalue='...'): a __repr__ that calls itself for the same object (on the same thread) returns
        /// fillvalue there instead of recursing forever.
        /// </summary>
        public static dynamic recursive_repr(string fillvalue = "...") =>
            new PyClosure("decorating_function", (a, kw) =>
            {
                var user_function = a.Length > 0 ? a[0] : null;
                var running = new HashSet<(int, int)>();
                var wrapper = new PyClosure((user_function as PyFunction)?.__name__ ?? "wrapper", (args, kwargs) =>
                {
                    var self = args.Length > 0 ? args[0] : null;
                    var key = (self == null ? 0 : RuntimeHelpers.GetHashCode(self), Environment.CurrentManagedThreadId);
                    lock (running) { if (!running.Add(key)) return fillvalue; }
                    try { return Builtins.__invoke_kw(user_function, args, kwargs); }
                    finally { lock (running) running.Remove(key); }
                });
                wrapper.__wrapped__ = user_function;
                wrapper.__doc__ = (user_function as PyFunction)?.__doc__;
                return wrapper;
            });
    }

    /// <summary>
    /// numbers: the numeric abstract base classes (Number ⊃ Complex ⊃ Real ⊃ Rational ⊃ Integral). issubclass(int,
    /// numbers.Integral) and the like hold; isinstance(5, numbers.Integral) needs the compiler's isinstance, which tests
    /// .NET types (it is False for Typhon's int and float today).
    /// </summary>
    internal static class numbers
    {
        internal abstract class Number
        {
            /// <summary>register(subclass): CPython records a virtual subclass; Typhon's classes are fixed (it returns subclass).</summary>
            public static object? register(object? subclass) => subclass;
        }
        internal abstract class Complex : Number { }
        internal abstract class Real : Complex { }
        internal abstract class Rational : Real { }
        internal abstract class Integral : Rational { }

        /// <summary>Whether a .NET type is one of Python's numbers under an ABC (int → Integral, float → Real, Fraction → Rational).</summary>
        internal static bool IsNumberType(Type t, Type abc)
        {
            bool isInt = t == typeof(long) || t == typeof(int) || t == typeof(short) || t == typeof(byte) || t == typeof(BigInteger) || t == typeof(bool);
            bool isFloat = t == typeof(double) || t == typeof(float) || t == typeof(decimal);
            bool isFraction = t == typeof(Fraction);
            bool isComplex = t == typeof(System.Numerics.Complex);
            if (abc == typeof(Integral)) return isInt;
            if (abc == typeof(Rational)) return isInt || isFraction;
            if (abc == typeof(Real)) return isInt || isFraction || isFloat;
            if (abc == typeof(Complex) || abc == typeof(Number)) return isInt || isFraction || isFloat || isComplex;
            return false;
        }
    }

    /// <summary>
    /// copyreg: the registry pickle consults for reducing objects (dispatch_table, pickle(), constructor()) and the
    /// extension code registry. Typhon has no pickle module yet; the registry is kept for code that fills it.
    /// </summary>
    internal static class copyreg
    {
        public static readonly OrderedDictionary<object, object?> dispatch_table = new OrderedDictionary<object, object?>(PyKeyComparer.Instance!);
        public static readonly OrderedDictionary<object, object?> _extension_registry = new OrderedDictionary<object, object?>(PyKeyComparer.Instance!);
        public static readonly OrderedDictionary<object, object?> _inverted_registry = new OrderedDictionary<object, object?>(PyKeyComparer.Instance!);
        public static readonly OrderedDictionary<object, object?> _extension_cache = new OrderedDictionary<object, object?>(PyKeyComparer.Instance!);

        /// <summary>pickle(ob_type, pickle_function, constructor_ob=None): how to reduce objects of a type.</summary>
        public static void pickle(object ob_type, object? pickle_function, object? constructor_ob = null)
        {
            if (pickle_function == null || !(pickle_function is PyFunction || pickle_function is Delegate || pickle_function is PyBoundMethod))
                throw new InvalidCastException("reduction functions must be callable");
            dispatch_table[ob_type] = pickle_function;
            if (constructor_ob != null) constructor(constructor_ob);
        }

        public static void constructor(object? @object)
        {
            if (@object == null) throw new InvalidCastException("constructors must be callable");
        }

        public static void add_extension(string module, string name, long code)
        {
            if (code < 1 || code > 0x7fffffff) throw new ArgumentException("code out of range");
            var key = (module, name);
            if (_extension_registry.TryGetValue(key, out var existing) && Builtins.eq(existing, code) && _inverted_registry.TryGetValue(code, out var k) && Builtins.eq(k, key)) return;
            if (_extension_registry.ContainsKey(key)) throw new ArgumentException($"key {Builtins.repr(key)} is already registered with code {Builtins.repr(_extension_registry[key])}");
            if (_inverted_registry.ContainsKey(code)) throw new ArgumentException($"code {code} is already in use for key {Builtins.repr(_inverted_registry[code])}");
            _extension_registry[key] = code;
            _inverted_registry[code] = key;
        }

        public static void remove_extension(string module, string name, long code)
        {
            var key = (module, name);
            if (!_extension_registry.TryGetValue(key, out var c) || !Builtins.eq(c, code) || !_inverted_registry.TryGetValue(code, out var k) || !Builtins.eq(k, key))
                throw new ArgumentException($"key {Builtins.repr(key)} is not registered with code {code}");
            _extension_registry.Remove(key);
            _inverted_registry.Remove(code);
            _extension_cache.Remove(code);
        }

        public static void clear_extension_cache() => _extension_cache.Clear();
    }
}
